   await check('GROUPS-02','大屏分组页逐人显示头像姓名积分，直接加减与个人历史正确',['V001','V005','V017'],async()=>{await restore(base());await click('[data-page="groups"]');let s=await state();assert.equal(await js(main,'document.querySelectorAll("[data-group-member]").length'),s.students.length);const id=s.students[0].id;for(const item of s.students){assert.equal(await js(main,`document.querySelector('[data-group-member="${item.id}"] .member-score').textContent`),'0');assert.ok(await js(main,`document.querySelector('[data-group-member="${item.id}"]').textContent.includes(${JSON.stringify(item.name)})`));}await click(`[data-group-member="${id}"] [data-do="quick-score"][data-delta="1"]`);await until(async()=>(await state()).students[0].score===1);assert.equal(await js(main,`document.querySelector('[data-group-member="${id}"] .member-score').textContent`),'1');assert.equal((await state()).students.filter(s=>s.score!==0).length,1);assert.equal((await state()).groupBases,undefined);await screenshot(main,'28-group-individual-scores');await click(`[data-group-member="${id}"] [data-do="student-history"]`);assert.ok(await js(main,'document.querySelector("#modal").textContent.includes("0 → 1")'));await click('[data-do="modal-close"]');await click(`[data-group-member="${id}"] [data-do="quick-score"][data-delta="-1"]`);await until(async()=>(await state()).students[0].score===0);assert.equal((await state()).students[0].growth,1);assert.equal(await js(main,'document.documentElement.scrollWidth<=innerWidth'),true);return {memberRows:12,groups:4,individualPlus:1,individualMinus:-1,independentBaseUnchanged:true,history:true};});
