   await check('FLOWER-01','红花双击按首次可见状态切换，320ms间隔第二击不受260ms单击延迟干扰',['V036'],async()=>{
    await restore(base());const before=await state(),cases=[];
    panel.hide();const singleTarget=await js(flower,`(()=>{const r=document.querySelector('.flower-button').getBoundingClientRect();return {x:Math.floor(r.left+r.width/2),y:Math.floor(r.top+r.height/2)};})()`);flower.webContents.sendInputEvent({type:'mouseDown',...singleTarget,button:'left',clickCount:1});flower.webContents.sendInputEvent({type:'mouseUp',...singleTarget,button:'left',clickCount:1});await until(()=>panel.isVisible());await sleep(350);assert.equal(panel.isVisible(),true,'Standalone single click must open and keep panel visible');
    const gesture=`(()=>{const b=document.querySelector('.flower-button');b.click();b.click();b.dispatchEvent(new MouseEvent('dblclick',{bubbles:true}));return true;})()`;
    panel.show();await js(flower,gesture);await until(()=>!panel.isVisible());await sleep(350);assert.equal(panel.isVisible(),false);await js(flower,gesture);await until(()=>panel.isVisible());await sleep(350);assert.equal(panel.isVisible(),true);
    for(const initiallyVisible of [false,true]){
     initiallyVisible?panel.show():panel.hide();assert.equal(panel.isVisible(),initiallyVisible);
     const target=await js(flower,`(()=>{const b=document.querySelector('.flower-button');window.qaFlowerEvents=[];if(!b.__qaFlowerTrace){for(const type of ['click','dblclick'])b.addEventListener(type,e=>qaFlowerEvents.push({type:e.type,detail:e.detail,timeStamp:e.timeStamp,isTrusted:e.isTrusted}),{capture:true});b.__qaFlowerTrace=true;}const r=b.getBoundingClientRect();return {x:Math.floor(r.left+r.width/2),y:Math.floor(r.top+r.height/2)};})()`);
     const mouse=count=>{flower.webContents.sendInputEvent({type:'mouseDown',...target,button:'left',clickCount:count});flower.webContents.sendInputEvent({type:'mouseUp',...target,button:'left',clickCount:count});};
     const start=Date.now();mouse(1);await sleep(320);const elapsedBeforeSecondMs=Date.now()-start,visibleAfterFirstDelay=panel.isVisible();mouse(2);await sleep(350);
     const events=await js(flower,'qaFlowerEvents'),actualVisible=panel.isVisible();cases.push({initiallyVisible,delayRequestedMs:320,elapsedBeforeSecondMs,visibleAfterFirstDelay,expectedVisible:!initiallyVisible,actualVisible,events});
     await screenshot(flower,'30-flower-delayed-'+(initiallyVisible?'visible':'hidden'));
    }
    const detail={standaloneNativeSingleClickPassed:true,zeroDelayDoubleClickPassed:true,nativeInputUsed:true,physicalPointerNotTested:true,cases,dataUnchanged:JSON.stringify(await state())===JSON.stringify(before),referenceLimit:'Real Linux Electron event-order test; no Windows OS double-click threshold or physical input validation'};
    fs.writeFileSync(path.join(out,'flower-double-click-timing.json'),JSON.stringify(detail,null,2));
    for(const test of cases){assert.equal(test.visibleAfterFirstDelay,true,'Initial single click must open before the delayed second click');assert.ok(test.events.some(e=>e.type==='click'&&e.detail===1));assert.ok(test.events.some(e=>e.type==='click'&&e.detail===2));assert.ok(test.events.some(e=>e.type==='dblclick'&&e.detail===2));assert.equal(test.actualVisible,test.expectedVisible,'320ms double click must toggle from initial '+(test.initiallyVisible?'visible':'hidden')+' state: '+JSON.stringify(test));}
    assert.deepEqual(await state(),before);return detail;
   });
