   await check('BACKUP-01','所有面板导出再恢复保留完整数据，为真实重启留存',['V013'],async()=>{await restore(base());let a=await state();await action({type:'student.update',id:a.students[0].id,photo:JSON.parse(fs.readFileSync(path.join(data,'legacy-input.json'))).students[0].photo});await action({type:'score',ids:[a.students[0].id],delta:7});await action({type:'panel.create',mode:'copy',name:'重启合成课堂乙'});let b=await state();await action({type:'score',ids:[b.students[1].id],delta:3});await action({type:'photos.visibility',value:false});await action({type:'timer.sound',sound:'laser'});const before=await state();savePath=path.join(out,'synthetic-all-panels-backup.json');assert.equal(await file({command:'backup'}),true);assert.deepEqual(JSON.parse(fs.readFileSync(savePath)),before);await action({type:'score',ids:[b.students[0].id],delta:100});openPath=savePath;const preview=await file({command:'restore-preview'});await file({command:'restore-apply',state:preview});const restored=await state();assert.deepEqual(stripRevision(restored),stripRevision(before));fs.writeFileSync(path.join(data,'expected-restart.json'),JSON.stringify(restored));await screenshot(main,'18-all-panels-restored');return {panels:restored.panels.others.length+1,backupBytes:fs.statSync(savePath).size,restoredExactExceptRevision:true};});
